package com.fream.back.domain.m85.service.command;

import com.fream.back.domain.m99.entity.Xtw92;
import com.fream.back.domain.m99.service.query.Xtw92QueryService;
import com.fream.back.domain.m30.entity.Xcc44;
import com.fream.back.domain.m30.service.p11.Xcc44QueryService;
import com.fream.back.domain.m85.entity.Xkh73Status;
import com.fream.back.domain.m85.entity.Xpj42;
import com.fream.back.domain.m85.entity.Xzt63;
import com.fream.back.domain.m85.repository.Xzt63Repository;
import com.fream.back.domain.m22.entity.Xjm45;
import com.fream.back.domain.m22.service.query.Xjm45QueryService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class Xzt63CommandService {

    private final Xzt63Repository saleBidRepository;
    private final Xjm45QueryService userQueryService;
    private final Xcc44QueryService productSizeQueryService;
    private final Xpj42CommandService saleCommandService;
    private final Xtw92QueryService orderBidQueryService;
    @Transactional
    public Xzt63 createSaleBid(String sellerEmail, Long productSizeId, int bidPrice,
                                 String returnAddress, String postalCode, String receiverPhone
                                , boolean isWarehouseStorage) {

        Xjm45 seller = userQueryService.findByEmail(sellerEmail);


        Xcc44 productSize = productSizeQueryService.findById(productSizeId)
                .orElseThrow(() -> new IllegalArgumentException("해당 상품 사이즈를 찾을 수 없습니다: " + productSizeId));


        Xpj42 sale = saleCommandService.createSale(seller, productSize, returnAddress, postalCode, receiverPhone,isWarehouseStorage);


        Xzt63 saleBid = Xzt63.builder()
                .seller(seller)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(Xkh73Status.PENDING)
                .sale(sale)
                .build();


        saleBid = saleBidRepository.save(saleBid);


        sale.assignSaleBid(saleBid);


        return saleBid;
    }
    @Transactional
    public Long createInstantSaleBid(Long orderBidId,
                                        String sellerEmail,
                                        String returnAddress,
                                        String postalCode,
                                        String receiverPhone) {

        Xpj42 sale=saleCommandService.createInstantSale(orderBidId,sellerEmail,returnAddress,postalCode,receiverPhone);

        Xtw92 orderBid = orderBidQueryService.findById(orderBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));



        Xzt63 saleBid = Xzt63.builder()
                .seller(sale.getSeller())
                .productSize(sale.getProductSize())
                .bidPrice(orderBid.getBidPrice())
                .status(Xkh73Status.MATCHED)
                .sale(sale)
                .order(orderBid.getOrder())
                .build();


        saleBid.assignSale(sale);
        saleBid.assignOrder(orderBid.getOrder());
        sale.assignSaleBid(saleBid);


        saleBidRepository.save(saleBid);


        return sale.getId();
    }

    @Transactional
    public void deleteSaleBid(Long saleBidId) {

        Xzt63 saleBid = saleBidRepository.findById(saleBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 SaleBid를 찾을 수 없습니다: " + saleBidId));


        if (saleBid.getOrder() != null) {
            throw new IllegalStateException("SaleBid는 Order와 연결되어 있으므로 삭제할 수 없습니다.");
        }


        if (saleBid.getSale() != null) {
            saleCommandService.deleteSale(saleBid.getSale().getId());
        }


        saleBidRepository.delete(saleBid);
    }
}
package com.fream.back.domain.m52.entity;

public enum Xbp24Type {


    TRADE(Xrv73.SHOPPING, "거래 관련 알림"),
    BID(Xrv73.SHOPPING, "입찰 관련 알림"),
    STORAGE(Xrv73.SHOPPING, "보관 관련 알림"),
    FAVORITE(Xrv73.SHOPPING, "관심 상품 관련 알림"),
    BENEFIT(Xrv73.SHOPPING, "혜택 관련 알림"),
    ANNOUNCEMENT(Xrv73.SHOPPING, "공지사항 알림"),
    REFUND(Xrv73.SHOPPING, "환불 관련 알림"),


    LIKE(Xrv73.STYLE, "좋아요 관련 알림"),
    COMMENT(Xrv73.STYLE, "댓글 관련 알림"),
    FOLLOW(Xrv73.STYLE, "팔로우 관련 알림");

    private final Xrv73 category;
    private final String description;

    Xbp24Type(Xrv73 category, String description) {
        this.category = category;
        this.description = description;
    }

    public Xrv73 getCategory() {
        return category;
